import type { Language, LocalNames } from '../i18n';
import type { LandPolygon } from '../types';
import generated from './generated/world-lakes.json';
import { inPolygon, wrapLon } from './world';

// Lake geometry is generated by scripts/prepare-map.mjs from Natural Earth v5.1.2 ne_50m_lakes (public domain).
// Rendering only: the simulation still treats lake cells as land (see isLand in world.ts).
export const LAKE_POLYGONS: LandPolygon[] = generated.polygons as LandPolygon[];

const LAKE_BOXES = LAKE_POLYGONS.map(({ outer }) => {
  const xs = outer.map(c => c[0]);
  const ys = outer.map(c => c[1]);
  return [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)] as const;
});

/** True where a mapped lake lies. The simulation still counts these points as land (see isLand in world.ts). */
export function isLake(lon: number, lat: number): boolean {
  const x = wrapLon(lon);
  return LAKE_POLYGONS.some((polygon, i) => {
    const [west, south, east, north] = LAKE_BOXES[i];
    return x >= west && x <= east && lat >= south && lat <= north && inPolygon(lon, lat, polygon);
  });
}

/** rank 2 = large lakes (>= 2 deg²: Superior, Baikal, Victoria, ...), 3 = all other named lakes. Same scale as `Sea.rank`. */
export interface Lake {
  name: string;
  nameKo?: string;
  /** Natural Earth ja / zh-CN / zh-TW names, only the ones the source has. */
  names?: LocalNames;
  lon: number;
  lat: number;
  scalerank: number;
  areaDeg2: number;
  /** Index of the lake's largest polygon in LAKE_POLYGONS; the label anchor lies inside it. */
  polygon: number;
  rank: 2 | 3;
}

export const LARGE_LAKE_AREA_DEG2 = 2;

// Natural Earth names that read badly as map labels (a transliterated "South Aral Sea", a Spanish "Lago" prefix).
const OVERRIDES: Record<string, { name?: string; nameKo?: string }> = {
  'Lago Titicaca': { name: 'Lake Titicaca' },
  'South Aral Sea': { nameKo: '남아랄해' },
  'North Aral Sea': { nameKo: '북아랄해' },
};

type Row = Omit<Lake, 'rank'>;

/** Named lakes, largest first. */
export const LAKES: Lake[] = (generated.names as Row[]).map(row => ({
  ...row,
  ...OVERRIDES[row.name],
  rank: row.areaDeg2 >= LARGE_LAKE_AREA_DEG2 ? 2 : 3,
}));

export const lakeName = (l: Lake, lang: Language): string => (lang === 'en' ? l.name : (lang === 'ko' ? l.nameKo : l.names?.[lang]) || l.name);

/** Minimum web zoom (see `webZoom`) at which each lake rank is labelled. */
export const LAKE_MIN_ZOOM: Record<Lake['rank'], number> = { 2: 4, 3: 5.5 };
